const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0];
// a small binary min-heap of numbers; the smaller half is stored negated to act as a max-heap
class MinHeap {
  constructor() { this.a = []; }
  get size() { return this.a.length; }
  peek() { return this.a[0]; }
  push(x) {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] <= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop() {
    const a = this.a;
    const top = a[0];
    const last = a.pop();
    if (a.length > 0) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let s = i;
        if (l < a.length && a[l] < a[s]) s = l;
        if (r < a.length && a[r] < a[s]) s = r;
        if (s === i) break;
        [a[s], a[i]] = [a[i], a[s]];
        i = s;
      }
    }
    return top;
  }
}
const low = new MinHeap(), high = new MinHeap();
const out = [];
for (let i = 1; i <= n; i++) {
  const x = tok[i];
  if (low.size > 0 && x > -low.peek()) high.push(x);
  else low.push(-x);
  if (low.size > high.size + 1) high.push(-low.pop());
  else if (high.size > low.size) low.push(-high.pop());
  out.push(-low.peek());
}
console.log(out.join(' '));

