import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken();
        int n = (int) st.nval;
        PriorityQueue<Long> low = new PriorityQueue<>(Collections.reverseOrder());   // the smaller half
        PriorityQueue<Long> high = new PriorityQueue<>();                           // the larger half
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            st.nextToken();
            long x = (long) st.nval;
            if (!low.isEmpty() && x > low.peek()) high.add(x);
            else low.add(x);
            if (low.size() > high.size() + 1) high.add(low.poll());
            else if (high.size() > low.size()) low.add(high.poll());
            if (i > 0) sb.append(' ');
            sb.append(low.peek());
        }
        System.out.println(sb);
    }
}

