#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    priority_queue<long long> low;                                                  // the smaller half (max-heap)
    priority_queue<long long, vector<long long>, greater<long long>> high;          // the larger half (min-heap)
    for (int i = 0; i < n; i++) {
        long long x;
        scanf("%lld", &x);
        if (!low.empty() && x > low.top()) high.push(x);
        else low.push(x);
        if (low.size() > high.size() + 1) { high.push(low.top()); low.pop(); }
        else if (high.size() > low.size()) { low.push(high.top()); high.pop(); }
        printf(i ? " %lld" : "%lld", low.top());
    }
    printf("\n");
    return 0;
}
